package com.example.quanlykhohang;
import android.os.Bundle; import android.widget.*;
public class AddProductActivity extends BaseActivity {
 protected void onCreate(Bundle b){super.onCreate(b);screen(R.layout.activity_add_product);Spinner s=findViewById(R.id.category);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,new String[]{"Điện tử","Thực phẩm","Văn phòng phẩm","Gia dụng","Khác"});a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);findViewById(R.id.back).setOnClickListener(v->finish());findViewById(R.id.save).setOnClickListener(v->{String name=input(R.id.name);if(name.isEmpty()){((EditText)findViewById(R.id.name)).setError("Nhập tên sản phẩm");return;}int price,qty;try{price=Integer.parseInt(input(R.id.price));if(price<=0)throw new NumberFormatException();}catch(NumberFormatException e){((EditText)findViewById(R.id.price)).setError("Giá phải là số nguyên lớn hơn 0");return;}try{qty=Integer.parseInt(input(R.id.quantity));if(qty<0)throw new NumberFormatException();}catch(NumberFormatException e){((EditText)findViewById(R.id.quantity)).setError("Số lượng phải là số nguyên không âm");return;}Product p=new Product(0,name,price,qty,s.getSelectedItem().toString(),((Switch)findViewById(R.id.active)).isChecked(),input(R.id.description));if(db.insertProduct(p)>0){toast("Đã lưu sản phẩm");finish();}else toast("Không thể lưu sản phẩm");});}
}